package com.hbm.client.forcefield;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.machine.forcefield.*;import java.util.List;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.resources.sounds.SimpleSoundInstance;import net.minecraft.network.chat.Component;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.entity.player.Inventory;import net.neoforged.neoforge.network.PacketDistributor;
/** Source176×168 panel: exact3slots/52px HE+health columns/18px toggle hitbox and icon. */
public final class ForceFieldScreen extends LegacyContainerScreen<ForceFieldMenu> {
 public ForceFieldScreen(ForceFieldMenu menu,Inventory inventory,Component title){super(menu,inventory,title,ForceFieldContent.id("textures/gui/gui_field.png"),176,168);}
 @Override protected void renderLabels(GuiGraphics graphics,int x,int y){graphics.drawString(font,title,imageWidth/2-font.width(title)/2,6,4210752,false);graphics.drawString(font,playerInventoryTitle,8,74,4210752,false);}
 @Override protected void renderBg(GuiGraphics graphics,float partial,int x,int y){super.renderBg(graphics,partial,x,y);var field=menu.field;int power=ForceFieldConfig.maxPower.signum()==0?0:field.power.multiply(java.math.BigInteger.valueOf(52)).divide(ForceFieldConfig.maxPower).intValue();if(power>0)drawLegacyRegion(graphics,8,69-power,176,52-power,16,power);int health=field.maxHealth==0?0:field.health*52/field.maxHealth;if(health>0)drawLegacyRegion(graphics,62,69-health,192,52-health,16,health);if(field.isOn)drawLegacyRegion(graphics,142,34,176,52,18,18);}
 @Override public void render(GuiGraphics graphics,int x,int y,float partial){super.render(graphics,x,y,partial);if(legacyInfoHovered(x,y,8,17,16,52))graphics.renderComponentTooltip(font,List.of(Component.literal(menu.field.power+" / "+ForceFieldConfig.maxPower+" HE")),x,y);if(legacyInfoHovered(x,y,62,17,16,52))graphics.renderComponentTooltip(font,List.of(Component.translatable("gui.hbm.forcefield.hp",menu.field.health,menu.field.maxHealth)),x,y);}
 @Override public boolean mouseClicked(double x,double y,int button){boolean handled=super.mouseClicked(x,y,button);if(legacyInfoHovered(x,y,142,34,18,18)){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));PacketDistributor.sendToServer(new ForceFieldControl(menu.containerId));return true;}return handled;}
}
